"""Tests for `gate.py citation-floor` -- a new gate implementing VER-18.
Design spec: docs/audits/2026-09-04-determinism-audit.md, sections 3.1, 5.

The per-paragraph auditor is a PRESENCE check: it verifies that claims
which ARE cited are cited correctly, and is structurally blind to a
paragraph that cites nothing. This gate counts SECONDARY citations only
(primary sources stay inline, so a raw count reads healthy on an article
that quotes primary texts constantly but engages no scholarship at all)
and fails if either floor in thresholds.json > citationFloor is breached.

tests/fixtures/gate/article-valid.md carries exactly 8 secondary citations
(matching authors "Cohen" / "Levi" in
tests/fixtures/gate/sources-valid.json) over ~113 words -- with the
default thresholds.json floors (minSecondaryPer1000Words=4.0,
minSecondaryTotal=8), the rate floor at that word count (~0.45) is far
below the absolute floor (8), so the absolute floor is the binding
constraint. That makes "exactly at the floor" and "one below it" a clean,
predictable pair for TST-08's mutation test.
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GATE = os.path.join(ROOT_DIR, "src", "scripts", "gate.py")
FIXTURES = os.path.join(ROOT_DIR, "tests", "fixtures", "gate")
VALID_ARTICLE_PATH = os.path.join(FIXTURES, "article-valid.md")
VALID_SOURCES_PATH = os.path.join(FIXTURES, "sources-valid.json")


def run_gate(*args):
    """Invoke gate.py as a real subprocess. Auto-injects a scratch
    --ledger into a throwaway tempdir when the caller didn't supply one --
    without this, gate.py resolves the ledger via $CLAUDE_PROJECT_DIR (or
    cwd) and would write into any REAL .academic-helper/session-state.json
    that happens to exist there (TST-09 spirit: no ambient-environment
    dependency, including this one).
    """
    if "--ledger" not in args and args:
        with tempfile.TemporaryDirectory() as ledger_dir:
            return subprocess.run(
                [sys.executable, GATE, *args, "--ledger", os.path.join(ledger_dir, "session-state.json")],
                capture_output=True,
                text=True,
                timeout=30,
            )
    return subprocess.run(
        [sys.executable, GATE, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


class TestFloorAtOrAboveBoundary(unittest.TestCase):
    def test_article_at_the_floor_passes(self):
        proc = run_gate("citation-floor", VALID_ARTICLE_PATH, "--sources", VALID_SOURCES_PATH, "--json")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")
        self.assertIn("secondary=8", payload["detail"])

    def test_article_one_secondary_below_floor_fails(self):
        """Plant the exact mutation from the acceptance spec: drop the
        article to one secondary citation below the floor.
        """
        with open(VALID_ARTICLE_PATH, encoding="utf-8") as fh:
            lines = fh.read().splitlines()
        # Drop the last non-empty citation-bearing line -> 7 secondary.
        while lines and lines[-1].strip() == "":
            lines.pop()
        lines.pop()
        below_floor_text = "\n".join(lines) + "\n"

        with tempfile.TemporaryDirectory() as tmpdir:
            article_path = os.path.join(tmpdir, "article.md")
            with open(article_path, "w", encoding="utf-8") as fh:
                fh.write(below_floor_text)
            proc = run_gate(
                "citation-floor", article_path, "--sources", VALID_SOURCES_PATH, "--json"
            )

        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "fail")
        self.assertIn("secondary=7", payload["detail"])
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("absolute-floor", checks)


class TestPresenceCheckBlindSpot(unittest.TestCase):
    def test_primary_only_article_reads_citation_heavy_but_fails(self):
        """The whole point of VER-18: an article can be full of inline
        primary-source references and still fail this gate, because none
        of them are secondary scholarship. A naive raw citation count
        would read this as healthy.
        """
        primary_only = "\n\n".join(
            [
                '# Article',
                'The verse states clearly (בראשית א, א) that the beginning matters.',
                'This is reinforced elsewhere ע"א in the same tractate.',
                'A further primary reference (שמות ב, ג) develops the point.',
                'And once more the text returns ע"ב to the same theme.',
            ]
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            article_path = os.path.join(tmpdir, "article.md")
            with open(article_path, "w", encoding="utf-8") as fh:
                fh.write(primary_only)
            proc = run_gate(
                "citation-floor", article_path, "--sources", VALID_SOURCES_PATH, "--json"
            )
        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertIn("secondary=0", payload["detail"])


class TestFootnoteCitations(unittest.TestCase):
    def test_footnote_marker_classified_via_its_definition_body(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            article_path = os.path.join(tmpdir, "article.md")
            body = "\n\n".join(
                [f"Claim number {i} needs support.[^{i}]" for i in range(1, 9)]
            )
            defs = "\n".join(
                [f"[^{i}]: Cohen, David, Historical Method, p. {i}." for i in range(1, 9)]
            )
            with open(article_path, "w", encoding="utf-8") as fh:
                fh.write(body + "\n\n" + defs + "\n")
            proc = run_gate(
                "citation-floor", article_path, "--sources", VALID_SOURCES_PATH, "--json"
            )
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertIn("secondary=8", payload["detail"])


