class TestThresholdsAreReadNotHardcoded(unittest.TestCase):
    def test_custom_thresholds_change_the_verdict(self):
        """The 8-citation valid article passes under the default floor
        (minSecondaryTotal=8) but must FAIL under a stricter custom
        thresholds file -- proving the floor is genuinely read from
        thresholds.json, never a hardcoded number.
        """
        with tempfile.TemporaryDirectory() as tmpdir:
            thresholds_path = os.path.join(tmpdir, "thresholds.json")
            with open(thresholds_path, "w", encoding="utf-8") as fh:
                json.dump(
                    {"citationFloor": {"minSecondaryPer1000Words": 4.0, "minSecondaryTotal": 20}},
                    fh,
                )
            proc = run_gate(
                "citation-floor",
                VALID_ARTICLE_PATH,
                "--sources",
                VALID_SOURCES_PATH,
                "--thresholds",
                thresholds_path,
                "--json",
            )
        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("absolute-floor", checks)

    def test_rate_floor_alone_can_fail_independently_of_absolute_floor(self):
        """The spec says the gate fails if EITHER floor is breached -- the
        two floors must be independently live, not just the absolute one.
        The valid fixture (113 words, 8 secondary) trivially clears the
        default rate floor (~0.45), so every other test in this file only
        ever exercises the absolute-floor branch. Here minSecondaryTotal is
        set low enough to be satisfied (1) while minSecondaryPer1000Words
        is raised so the rate floor (100 * 113/1000 = 11.3) sits above the
        8 actual secondary citations -- isolating a rate-only failure.
        """
        with tempfile.TemporaryDirectory() as tmpdir:
            thresholds_path = os.path.join(tmpdir, "thresholds.json")
            with open(thresholds_path, "w", encoding="utf-8") as fh:
                json.dump(
                    {"citationFloor": {"minSecondaryPer1000Words": 100.0, "minSecondaryTotal": 1}},
                    fh,
                )
            proc = run_gate(
                "citation-floor",
                VALID_ARTICLE_PATH,
                "--sources",
                VALID_SOURCES_PATH,
                "--thresholds",
                thresholds_path,
                "--json",
            )
        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("rate-floor", checks)
        self.assertNotIn("absolute-floor", checks)


if __name__ == "__main__":
    unittest.main()
